import 'package:flutter/material.dart';
import '../api.dart';
class SettingsScreen extends StatefulWidget { const SettingsScreen({super.key}); @override State<SettingsScreen> createState() => _SettingsScreenState(); }
class _SettingsScreenState extends State<SettingsScreen> { final api = JopetsApi(); String? role; @override void initState() { super.initState(); api.role().then((value) { if (mounted) setState(() => role = value); }); } Future<void> logout() async { await api.logout(); if (mounted) Navigator.of(context).popUntil((route) => route.isFirst); } @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Configuración')), body: ListView(children: [ListTile(leading: const CircleAvatar(child: Icon(Icons.person)), title: Text(role ?? 'Cuenta autenticada'), subtitle: const Text('Identidad obtenida de la sesión Django')), const Divider(), const ListTile(leading: Icon(Icons.lock), title: Text('Cambiar contraseña')), const ListTile(leading: Icon(Icons.payment), title: Text('Métodos de pago')), const ListTile(leading: Icon(Icons.help), title: Text('Ayuda y soporte')), ListTile(leading: const Icon(Icons.logout, color: Colors.red), title: const Text('Cerrar sesión', style: TextStyle(color: Colors.red)), onTap: logout)])); }
